// Regenerates test/vectors/jws_envelope.json — the committed JWS
// signed-envelope vectors an off-the-shelf verifier checks
// (tool/verify_jws_vectors.mjs). Run from packages/at_client:
//
//   dart tool/generate_jws_vectors.dart
//
// The keys in the vector file are TEST FIXTURES generated by this script,
// never used anywhere else; the privates are committed so the RS256 arms can
// be re-signed and compared byte-for-byte (PKCS#1 v1.5 is deterministic —
// ML-DSA is hedged, so those arms are verified rather than re-signed).
//
// The `rs256` and `mlDsa65` arms are envelopes as at_client 4.0.0 signed
// them, naming no Atsign. This build cannot produce them, so they are carried
// over verbatim and the script refuses to run without them.
import 'dart:convert';
import 'dart:io';

import 'package:at_chops/at_chops.dart';
import 'package:at_client/src/signing/envelope_signature.dart';

Future<void> main() async {
  const payload = {'doc': 'JWS signed-envelope vector', 'n': 1};
  const atSign = '@alice';

  final existing = File('test/vectors/jws_envelope.json');
  if (!existing.existsSync()) {
    stderr.writeln('${existing.path} is missing, and its at_client 4.0.0 arms '
        'cannot be regenerated');
    exit(1);
  }
  final prior = jsonDecode(existing.readAsStringSync()) as Map<String, dynamic>;
  final frozenRs = prior['rs256'] as Map<String, dynamic>;
  final frozenMl = prior['mlDsa65'] as Map<String, dynamic>;

  // NOTE: the new arms reuse the frozen arms' key material, so the golden
  // file's diff shows what moved on the wire and nothing else.
  final rsaPublic = frozenRs['apskPublicKey'] as String;
  final rsaPrivate = frozenRs['privateKey'] as String;
  final mlDsaPublic = frozenMl['publicKey'] as String;
  final mlDsaSecret = frozenMl['secretKey'] as String;

  final rsaEnvelope = signEnvelope(payload,
      keys: [
        ApkamSigningKeys(
            algorithm: SigningAlgoType.rsa2048,
            publicKey: rsaPublic,
            privateKey: rsaPrivate)
      ],
      type: EnvelopeType.app,
      atSign: atSign,
      enrollmentId: 'vector-1');

  final mlDsaEnvelope = signEnvelope(payload,
      keys: [
        ApkamSigningKeys(
            algorithm: SigningAlgoType.mldsa65,
            publicKey: mlDsaPublic,
            privateKey: mlDsaSecret)
      ],
      type: EnvelopeType.app,
      atSign: atSign,
      enrollmentId: 'vector-1');

  final out = const JsonEncoder.withIndent('  ').convert({
    'comment': 'JWS signed-envelope vectors, RFC 7515 general JSON '
        'serialization. Each protected header carries a `typ` naming what the '
        'envelope was signed for, and a verifier is handed the type it '
        'expects rather than reading this one. The rs256 and mlDsa65 arms are '
        'envelopes as at_client 4.0.0 signed them, naming no Atsign, and are '
        'frozen; the rs256Iss and mlDsa65Iss arms name the signer\'s Atsign '
        'as iss. Test fixtures only — the keys exist for this file alone. See '
        'docs/projects/pq/decisions.md 60.4.',
    'payload': payload,
    'rs256': frozenRs,
    'mlDsa65': frozenMl,
    'rs256Iss': {
      'envelope': rsaEnvelope,
      // The _apsk form a verifier fetches: the bare base64-DER RSA string.
      'apskPublicKey': rsaPublic,
      'privateKey': rsaPrivate,
    },
    'mlDsa65Iss': {
      'envelope': mlDsaEnvelope,
      // The raw ML-DSA-65 public key, base64 — what an _apsk entry's `pub`
      // carries.
      'publicKey': mlDsaPublic,
      'secretKey': mlDsaSecret,
    },
  });

  existing.writeAsStringSync('$out\n');
  stdout.writeln('wrote ${existing.path}');
}
